package chapter13;
import javax.swing.*; import java.awt.*; import java.awt.geom.*; import java.awt.event.*; import java.util.*;
public class JColorChooserShapes extends JPanel{Random r=new Random();String shape="Rectangle";Color color=Color.BLACK;JColorChooserShapes(){JComboBox<String>b=new JComboBox<>(new String[]{"Rectangle","Oval","Line"});JButton c=new JButton("Choose Color");b.addActionListener(e->{shape=(String)b.getSelectedItem();repaint();});c.addActionListener(e->{Color z=JColorChooser.showDialog(this,"Choose Color",color);if(z!=null){color=z;repaint();}});add(b);add(c);}protected void paintComponent(Graphics g){super.paintComponent(g);g.setColor(color);for(int i=0;i<20;i++){int x=r.nextInt(Math.max(1,getWidth()-80)),y=45+r.nextInt(Math.max(1,getHeight()-100)),w=20+r.nextInt(70),h=20+r.nextInt(70);if(shape.equals("Rectangle"))g.drawRect(x,y,w,h);else if(shape.equals("Oval"))g.drawOval(x,y,w,h);else g.drawLine(x,y,x+w,y+h);}}public static void main(String[]a){ConcentricCirclesArc.show("13.30",new JColorChooserShapes(),650,450);}}
